export const CONTINENTS = [
  'All World',
  'Europe',
  'Asia',
  'Africa',
  'North America',
  'South America',
  'Oceania',
] as const;

export type Continent = typeof CONTINENTS[number];

// Helper to normalize user query string
export function normalizeCountryInput(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_'’`~()]/g, '')
    .replace(/\s{2,}/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

// Check match against canonical name and aliases
export function isMatchCountry(input: string, country: Country): boolean {
  const norm = normalizeCountryInput(input);
  if (!norm) return false;

  const normName = normalizeCountryInput(country.name);
  if (norm === normName) return true;

  return country.aliases.some(alias => normalizeCountryInput(alias) === norm);
}

// Flag URL generator
export function getFlagUrl(code: string): string {
  return `https://flagcdn.com/w320/${code.toLowerCase()}.png`;
}
